import django
from django.apps import AppConfig
from django.conf import settings


class ReproConfig(AppConfig):
    label = "repro"


settings.configure(
    DEBUG=True,
    DATABASES={
        "default": {"ENGINE": "django.db.backends.sqlite3", "NAME": "C:/Windows/Temp/nk33582_repro/db1.sqlite3"},
        "other": {"ENGINE": "django.db.backends.sqlite3", "NAME": "C:/Windows/Temp/nk33582_repro/db2.sqlite3"},
    },
    INSTALLED_APPS=[ReproConfig("repro", sys.modules["__main__"])],
    USE_TZ=True,
)
django.setup()

from django.db import models


class AuthorManager(models.Manager):
    def get_by_natural_key(self, name):
        return self.get(name=name)


class BookManager(models.Manager):
    def get_by_natural_key(self, title, author_name):
        return self.get(title=title, author__name=author_name)


class Author(models.Model):
    name = models.CharField(max_length=100)
    objects = AuthorManager()

    class Meta:
        app_label = "repro"

    def natural_key(self):
        return (self.name,)


class Book(models.Model):
    title = models.CharField(max_length=100)
    author = models.ForeignKey(Author, on_delete=models.CASCADE)
    objects = BookManager()

    class Meta:
        app_label = "repro"

    def natural_key(self):
        return (self.title,) + self.author.natural_key()


from django.core.management import call_command
from django.db import connections

for alias in ("default", "other"):
    with connections[alias].schema_editor() as se:
        se.create_model(Author)
        se.create_model(Book)

# Load into NON-DEFAULT db first, with default db still empty
# (the ticket's failing scenario: "problem doesn't appear if the data is
# already present in the default DB")
call_command("loaddata", "repro", database="other", format="json", verbosity=0)
print("other db: OK")

# default db must keep working too
call_command("loaddata", "repro", format="json", verbosity=0)
print("default db: OK")

assert Book.objects.using("other").count() == 1, "expected 1 book in other db"
assert Book.objects.count() == 1, "expected 1 book in default db"
print("rows in both dbs: OK")
